def emit(kind, obj):
    print("LIREATE_" + kind + " " + json.dumps(obj, ensure_ascii=False), flush=True)

def normalize(u, base=ROOT):
    try:
        p = up.urlsplit(up.urljoin(base, html.unescape(u.strip())))
        if p.scheme not in ("http", "https") or p.hostname not in ("lireate.ru", "www.lireate.ru"):
            return None
        path = re.sub(r"/+", "/", p.path or "/")
        if re.search(r"\.(?:jpe?g|png|gif|webp|avif|svg|ico|css|js|map|pdf|zip|rar|docx?|xlsx?|pptx?|xml|txt|woff2?|ttf|eot|mp[34]|webm)(?:$|/)", path, re.I):
            return None
        if re.match(r"/(?:admin|office|system|scripts|data|core|vendor|cron|assets|files|uploads)(?:/|$)", path, re.I):
            return None
        query = up.parse_qs(p.query)
        if query:
            if path.rstrip("/") != "/news" or any(k not in ("num", "category", "view", "page") for k in query):
                return None
            if any(len(v)!=1 or (k!="view" and not v[0].isdigit()) or (k=="view" and v[0]!="news") for k,v in query.items()):
                return None
            if int(query.get("num",["0"])[0]) > 50 or int(query.get("page",["0"])[0]) > 50 or int(query.get("category",["0"])[0]) > 100:
                return None
        return up.urlunsplit(("https", "lireate.ru", path, up.urlencode(sorted((k,v[0]) for k,v in query.items())), ""))
    except Exception:
        return None

def read_url(url):
    req = ur.Request(url, headers={"User-Agent": UA, "Accept": "text/html,application/xhtml+xml,application/xml,text/plain;q=0.8", "Accept-Encoding":"gzip"})
    try:
        res = ur.urlopen(req, timeout=18)
    except urllib.error.HTTPError as e:
        res = e
    with res:
        data = res.read(4_000_001)
        if res.headers.get("Content-Encoding", "").lower() == "gzip":
            data = gzip.decompress(data)
        charset = res.headers.get_content_charset() or "utf-8"
        body = data.decode(charset, errors="replace")
        return res.code, res.geturl(), res.headers.get("Content-Type", ""), res.headers.get("X-Robots-Tag", ""), body[:4_000_000]

class PageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.title=[]; self.h1=[]; self.links=[]; self.canonical=""; self.description=""; self.robots=""; self.intitle=False; self.inh1=False
    def handle_starttag(self, tag, attrs):
        a=dict(attrs)
        if tag=="title": self.intitle=True
        if tag=="h1": self.inh1=True; self.h1.append("")
        if tag=="a" and a.get("href"): self.links.append(a["href"])
        if tag=="link" and "canonical" in a.get("rel","").lower().split(): self.canonical=a.get("href","")
        if tag=="meta":
            name=a.get("name","").lower()
            if name=="description": self.description=a.get("content","")
            if name in ("robots","googlebot","yandex"): self.robots += name+":"+a.get("content","")+" "
    def handle_endtag(self, tag):
        if tag=="title": self.intitle=False
        if tag=="h1": self.inh1=False
    def handle_data(self, value):
        if self.intitle: self.title.append(value)
        if self.inh1 and self.h1: self.h1[-1]+=value
def compact(s): return re.sub(r"\s+"," ",s).strip()

def page(url):
    r={"url":url, "checked_at":datetime.datetime.now(datetime.timezone.utc).isoformat()}
    links=[]
    try:
        code, final, ctype, xrobots, body=read_url(url)
        r.update(status=code, final_url=final, content_type=ctype)
        if "html" in ctype or "<html" in body[:1000].lower():
            p=PageParser(); p.feed(body)
            r.update(title=compact("".join(p.title)), h1=[compact(s) for s in p.h1], description=compact(p.description), canonical=up.urljoin(final,p.canonical) if p.canonical else "", robots=compact(p.robots+" "+xrobots))
            links=sorted(set(filter(None,(normalize(h,final) for h in p.links))))
        else: r["error"]="non_html"
    except Exception as e:
        r.update(status=0,error=type(e).__name__+": "+str(e)[:200])
    return r, links

robot_sitemaps=[]
try:
    code,final,ctype,xr,body=read_url(ROOT+"robots.txt")
    emit("ROBOTS", {"status":code,"url":final,"text":body[:16000]})
    if code==200:
        rpobj=rp.RobotFileParser()
        rpobj.parse(body.splitlines())
        robot_sitemaps=re.findall(r"(?im)^sitemap:\s*(\S+)",body)
    elif code not in (404,410):
        events.append({"type":"robots_unavailable","status":code})
except Exception as e:
    events.append({"type":"robots_fetch_error","detail":str(e)[:200]})

def sitemap(url):
    if url in maps_seen or len(maps_seen)>=20 or time.monotonic()>DEADLINE: return
    p=up.urlsplit(url)
    if p.hostname not in ("lireate.ru","www.lireate.ru"): return
    maps_seen.add(url)
    try:
        code,final,ctype,xr,body=read_url(url)
        if code!=200: raise ValueError("HTTP "+str(code))
        root=ET.fromstring(body)
        locs=[e.text.strip() for e in root.iter() if e.tag.rsplit("}",1)[-1]=="loc" and e.text]
        emit("SITEMAP",{"url":url,"type":root.tag.rsplit("}",1)[-1],"entries":len(locs)})
        if root.tag.rsplit("}",1)[-1]=="sitemapindex":
            for s in locs: sitemap(s)
        else:
            sitemap_urls.update(filter(None,(normalize(s) for s in locs)))
    except Exception as e:
        events.append({"type":"sitemap_error","url":url,"detail":str(e)[:200]})

for sm in dict.fromkeys(robot_sitemaps+[ROOT+"sitemap.xml",ROOT+"sitemap_index.xml",ROOT+"wp-sitemap.xml"]):
    sitemap(sm)
pending={}
def offer(u, source):
    u=normalize(u)
    if u and u not in seen and u not in pending:
        pending[u]=source
seen=set()
for u in sorted(sitemap_urls): offer(u,"sitemap")
for u in SEEDS: offer(u,"known_public_url")
for u in [ROOT+"news/?view=news&page=2",ROOT+"news/?view=news&page=3",ROOT+"news/?view=news&page=27"]: offer(u,"pagination_sample")
